{"path":"assets/css/styles.css","content":"/* Playful premium aura editorial styles */
:root{
  --bg:#fbfffd;--muted:#6b6b6b;--accent1:#7bd3ff;--accent2:#9be7c4;--ink:#112;
  --radius:12px;--card-bg:rgba(255,255,255,0.85);
}
*{box-sizing:border-box}
body.aura{font-family: system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:var(--ink);background:linear-gradient(180deg,#f7fff9 0%,#f1fbff 100%);}
.wrap{max-width:1080px;margin:0 auto;padding:2rem}
.site-header{background:transparent;padding:1rem 0;position:relative}
.brand{font-weight:700;color:var(--ink);text-decoration:none;font-size:1.2rem}
.main-nav{display:flex;gap:1rem;align-items:center}
.main-nav a{color:var(--ink);text-decoration:none;padding:.4rem .6rem;border-radius:8px}
.main-nav a.cta{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#013;padding:.4rem .8rem}
.nav-toggle{display:none;background:none;border:none;font-size:1.4rem}

.hero{position:relative;padding:3rem 0 2rem;overflow:visible}
.hero-grid{display:grid;grid-template-columns:1fr 380px;gap:2rem;align-items:center}
.hero-copy h1{font-size:2.2rem;margin:0 0 .6rem}
.lead{font-size:1.05rem;color:var(--muted)}
.meta{font-size:.95rem;color:#356}
.hero-visual{position:relative}
.hero-blob{width:100%;height:auto;display:block}
.hero-card{position:absolute;right:10px;bottom:10px;background:var(--card-bg);padding:1rem;border-radius:10px;box-shadow:0 6px 20px rgba(5,10,10,0.06)}
.hero-ctas .btn{margin-right:.6rem}

.section{padding:2rem 0}
.story{background:linear-gradient(90deg,rgba(190,245,230,0.25),rgba(240,250,255,0.55));border-radius:14px;padding:2rem}
.bullets{display:flex;gap:1.2rem;flex-wrap:wrap;list-style:none;padding:0;margin:.8rem 0 0}
.bullets li{background:#fff;padding:.6rem .8rem;border-radius:10px;box-shadow:0 4px 12px rgba(10,20,20,0.03)}

.framework-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem;margin-top:1rem}
.card{background:var(--card-bg);padding:1rem;border-radius:12px}

.offers-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}
.offer{background:#fff;padding:1rem;border-radius:12px;box-shadow:0 6px 18px rgba(4,10,10,0.04)}
.offer.highlight{border:2px solid rgba(123,211,255,0.25);transform:translateY(-6px)}

.pricing-preview .pricing-tiles{display:flex;gap:1rem;margin:1rem 0}
.tile{background:linear-gradient(180deg,#fff,#f7fffb);padding:.8rem;border-radius:12px;box-shadow:0 6px 18px rgba(4,10,10,0.03)}

.testimonials-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem}
.quote{background:var(--card-bg);padding:1rem;border-left:4px solid var(--accent1);border-radius:8px}

.final-cta{background:linear-gradient(90deg,rgba(123,211,255,0.08),rgba(155,231,196,0.06));padding:1.6rem;border-radius:12px;margin-top:1rem}
.cta-grid{display:flex;justify-content:space-between;align-items:center}
.cta-actions .btn{margin-left:.6rem}

.btn{display:inline-block;text-decoration:none;padding:.6rem 1rem;border-radius:10px;background:#fff;color:var(--ink);border:1px solid rgba(0,0,0,0.05)}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#023}
.btn.ghost{background:transparent;border:1px dashed rgba(10,20,20,0.08)}
.btn.small{padding:.4rem .6rem;font-size:.9rem}

.site-footer{padding:2rem 0;margin-top:2rem;border-top:1px solid rgba(10,20,20,0.04)}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center}

.pattern{position:absolute;right:-40px;top:30px;width:220px;height:220px;opacity:.12}

@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr;}
  .framework-grid{grid-template-columns:repeat(2,1fr)}
  .offers-grid{grid-template-columns:1fr}
  .testimonials-grid{grid-template-columns:1fr}
  .nav-toggle{display:block}
  .main-nav{display:none;flex-direction:column;position:absolute;right:1rem;top:64px;background:#fff;padding:1rem;border-radius:10px;box-shadow:0 10px 30px rgba(0,0,0,0.08)}
  .main-nav.open{display:flex}
}

/* Decorative accessibility helpers */
.visually-hidden{position:absolute!important;height:1px;width:1px;overflow:hidden;clip:rect(1px,1px,1px,1px);white-space:nowrap}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile nav toggle
  var toggle=document.getElementById('navToggle');
  var nav=document.getElementById('mainNav');
  if(toggle && nav){
    toggle.addEventListener('click',function(){
      nav.classList.toggle('open');
    });
  }

  // Smooth scroll for same-page anchors
  document.addEventListener('click',function(e){
    var t=e.target.closest('a');
    if(!t) return;
    var href=t.getAttribute('href');
    if(href && href.indexOf('#')===0){
      e.preventDefault();
      var el=document.querySelector(href);
      if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
    }
  });

  // Simple CTA form behavior (if on a page with a form)
  document.addEventListener('submit',function(e){
    var form=e.target;
    if(form && form.classList && form.classList.contains('js-cta-form')){
      e.preventDefault();
      var btn=form.querySelector('button[type=submit]');
      if(btn) btn.disabled=true;
      var msg=document.createElement('div');
      msg.className='form-msg';
      msg.textContent='Thanks — we received your request. Our team will follow up to schedule a consult.';
      form.appendChild(msg);
      setTimeout(function(){ if(btn) btn.disabled=false; },2500);
    }
  });
})();"} 
